	TA_Base_Core::IRASubscribers::SubscriberType Radio::getSubscriberType(TA_Base_Bus::IRadioCorbaDef::SubscriberType type) const
	{
		FUNCTION_ENTRY("getSubscriberType");

		TA_Base_Core::IRASubscribers::SubscriberType subscriberType = TA_Base_Core::IRASubscribers::INVALID;

		switch (type)
		{
		case TA_Base_Bus::IRadioCorbaDef::SubscriberType::INDIVIDUAL_SUBSCRIBER:
		{
			subscriberType = TA_Base_Core::IRASubscribers::INDIVIDUAL;
			break;
		}
		case TA_Base_Bus::IRadioCorbaDef::SubscriberType::GROUP_SUBSCRIBER:
		{
			subscriberType = TA_Base_Core::IRASubscribers::GROUP;
			break;
		}
		case TA_Base_Bus::IRadioCorbaDef::SubscriberType::MOBILE_SUBSCRIBER:
		{
			subscriberType = TA_Base_Core::IRASubscribers::MOBILE;
			break;
		}
		case TA_Base_Bus::IRadioCorbaDef::SubscriberType::PATCH_SUBSCRIBER:
		{
			subscriberType = TA_Base_Core::IRASubscribers::PATCH_GROUP;
			break;
		}
		case TA_Base_Bus::IRadioCorbaDef::SubscriberType::DISPATCHER_SUBSCRIBER:
		{
			subscriberType = TA_Base_Core::IRASubscribers::DISPATCHER;
			break;
		}
		}

		FUNCTION_EXIT;
		return subscriberType;
	}

	void Radio::setAllSubscribers(const TA_Base_Bus::IRadioCorbaDef::SubscriberList& list)
	{
		FUNCTION_ENTRY("setAllSubscribers");

		try
		{
			// Clear all subscriber data
			TA_Base_Core::RASubscribersAccessFactory::getInstance().deleteAllSubscribers();

			// Create the subscribers object...
			IRASubscribers* subscriber;


			for (unsigned int i = 0; i < list.length(); i++)
			{
				TA_Base_Core::IRASubscribers::SubscriberType subscriberType = getSubscriberType(list[i].type);
				if (subscriberType == TA_Base_Core::IRASubscribers::INVALID)
				{
					LOG_GENERIC(SourceInfo, TA_Base_Core::DebugUtil::DebugError, "Invalid subscriber type, not applying changes to subscriber");
				}
				else
				{
					subscriber = new TA_Base_Core::RASubscribers(list[i].TSI.in(),
						list[i].subscriberName.in(),
						subscriberType,
						list[i].locationName.in(),
						list[i].locationKey,
						true,
						list[i].ownerTSI.in());

					// Now that we have the subscriber, simply apply the changes 
					subscriber->applyChanges();

					delete subscriber;
					subscriber = NULL;
				}

			}
		}
		catch (...)
		{

		}
			

		FUNCTION_EXIT;
	}

