	void Radio::retrieveCallStackHistory()
	{
		FUNCTION_ENTRY("retrieveCallStackHistory");
		// Get the selected calls list from the database
		std::vector<TA_Base_Core::IRACallStackHistory*> callStack =
			TA_Base_Core::RACallStackHistoryAccessFactory::getInstance().getFullList();

		RadioUpdateCallStackHistory message;
		message.isRetrieved = true;

		for (unsigned int i = 0; i < callStack.size(); i++)
		{
			message.callStackHistoryList[i].profile = callStack[i]->getProfileName().c_str();
			message.callStackHistoryList[i].locationKey = callStack[i]->getLocationKey();
			message.callStackHistoryList[i].identifier = callStack[i]->getIdentifier().c_str();
			message.callStackHistoryList[i].location = callStack[i]->getLocation().c_str();
			message.callStackHistoryList[i].timestamp = callStack[i]->getTimestamp();

			IRACallStackHistory::CallType type = callStack[i]->getCallType();

			switch (type)
			{
			case IRACallStackHistory::CALL_INVALID:
			{
				message.callStackHistoryList[i].callType = EStackCallType::CALL_INVALID;
				break;
			}
			case IRACallStackHistory::VOICE:
			{
				message.callStackHistoryList[i].callType = EStackCallType::VOICE;
				break;
			}
			case IRACallStackHistory::CONFERENCE:
			{
				message.callStackHistoryList[i].callType = EStackCallType::CONFERENCE;
				break;
			}
			case IRACallStackHistory::TEXT:
			{
				message.callStackHistoryList[i].callType = EStackCallType::TEXT;
				break;
			}
			case IRACallStackHistory::GROUP_ACK:
			{
				message.callStackHistoryList[i].callType = EStackCallType::GROUP_ACK;
				break;
			}
			case IRACallStackHistory::GROUP_UNACK:
			{
				message.callStackHistoryList[i].callType = EStackCallType::GROUP_UNACK;
				break;
			}
			case IRACallStackHistory::GROUP_BROADCAST:
			{
				message.callStackHistoryList[i].callType = EStackCallType::GROUP_BROADCAST;
				break;
			}
			case IRACallStackHistory::MISSED:
			{
				message.callStackHistoryList[i].callType = EStackCallType::MISSED;
				break;
			}
			case IRACallStackHistory::FAILED:
			{
				message.callStackHistoryList[i].callType = EStackCallType::FAILED;
				break;
			}
			case IRACallStackHistory::ENDED:
			{
				message.callStackHistoryList[i].callType = EStackCallType::ENDED;
				break;
			}
			}

			IRACallStackHistory::OriginType otype = callStack[i]->getOrigin();

			switch (otype)
			{
			case IRACallStackHistory::ORIGIN_INVALID:
			{
				message.callStackHistoryList[i].originType = EOriginType::ORIGIN_INVALID;
				break;
			}
			case IRACallStackHistory::INBOUND:
			{
				message.callStackHistoryList[i].originType = EOriginType::INBOUND;
				break;
			}
			case IRACallStackHistory::OUTBOUND:
			{
				message.callStackHistoryList[i].originType = EOriginType::OUTBOUND;
				break;
			}
			}

		}

		RadioStateUpdateBroadcaster::getInstance()->sendRadioUpdateCallStackHistory(message);
		FUNCTION_EXIT;

	}

