	void Radio::addCallStackEntry(const char* profile, ta_uint32 locationKey, ta_uint32 timestamp, TA_Base_Bus::IRadioCorbaDef::EOriginType originType, TA_Base_Bus::IRadioCorbaDef::EStackCallType callType, const char* identifier, const char* location, bool isEmergency, const char* tsi)
	{
		FUNCTION_ENTRY("addCallStackEntry");

		EStackCallType scType;
		EOriginType oriType;
		TA_Base_Core::IRACallStackHistory::OriginType oType;

		switch (originType)
		{
		case TA_Base_Bus::IRadioCorbaDef::ORIGIN_INVALID:
		{
			oType = TA_Base_Core::IRACallStackHistory::ORIGIN_INVALID;
			oriType = EOriginType::ORIGIN_INVALID;
			break;
		}
		case TA_Base_Bus::IRadioCorbaDef::INBOUND:
		{
			oType = TA_Base_Core::IRACallStackHistory::INBOUND;
			oriType = EOriginType::INBOUND;
			break;
		}
		case TA_Base_Bus::IRadioCorbaDef::OUTBOUND:
		{
			oType = TA_Base_Core::IRACallStackHistory::OUTBOUND;
			oriType = EOriginType::OUTBOUND;
			break;
		}
		}

		TA_Base_Core::IRACallStackHistory::CallType cType;

		switch (callType)
		{
		case TA_Base_Bus::IRadioCorbaDef::CALL_INVALID:
		{
			cType = TA_Base_Core::IRACallStackHistory::CALL_INVALID;
			scType = EStackCallType::CALL_INVALID;
			break;
		}
		case TA_Base_Bus::IRadioCorbaDef::VOICE:
		{
			cType = TA_Base_Core::IRACallStackHistory::VOICE;
			scType = EStackCallType::VOICE;
			break;
		}
		case TA_Base_Bus::IRadioCorbaDef::CONFERENCE:
		{
			cType = TA_Base_Core::IRACallStackHistory::CONFERENCE;
			scType = EStackCallType::CONFERENCE;
			break;
		}
		case TA_Base_Bus::IRadioCorbaDef::TEXT:
		{
			cType = TA_Base_Core::IRACallStackHistory::TEXT;
			scType = EStackCallType::TEXT;
			break;
		}
		case TA_Base_Bus::IRadioCorbaDef::GROUP_ACK:
		{
			cType = TA_Base_Core::IRACallStackHistory::GROUP_ACK;
			scType = EStackCallType::GROUP_ACK;
			break;
		}
		case TA_Base_Bus::IRadioCorbaDef::GROUP_UNACK:
		{
			cType = TA_Base_Core::IRACallStackHistory::GROUP_UNACK;
			scType = EStackCallType::GROUP_UNACK;
			break;
		}
		case TA_Base_Bus::IRadioCorbaDef::GROUP_BROADCAST:
		{
			cType = TA_Base_Core::IRACallStackHistory::GROUP_BROADCAST;
			scType = EStackCallType::GROUP_BROADCAST;
			break;
		}
		case TA_Base_Bus::IRadioCorbaDef::MISSED:
		{
			cType = TA_Base_Core::IRACallStackHistory::MISSED;
			scType = EStackCallType::MISSED;
			break;
		}
		case TA_Base_Bus::IRadioCorbaDef::FAILED:
		{
			cType = TA_Base_Core::IRACallStackHistory::FAILED;
			scType = EStackCallType::FAILED;
			break;
		}
		case TA_Base_Bus::IRadioCorbaDef::ENDED:
		{
			cType = TA_Base_Core::IRACallStackHistory::ENDED;
			scType = EStackCallType::ENDED;
			break;
		}
	
		}
		

		TA_Base_Core::RACallStackHistoryAccessFactory::getInstance().addCallStackEntry(profile, locationKey, timestamp, oType, cType, identifier, location, isEmergency, tsi);

		if (m_active)
		{
			RadioAddCallStackEntry message;
			message.profile = profile;
			message.locationKey = locationKey;
			message.timestamp = timestamp;
			message.originType = oriType;
			message.callType = scType;
			message.identifier = identifier;
			message.location = location;
			message.isEmergency = isEmergency;
			message.tsi = tsi;

			// Send Comms Message
			m_callback.sendCommsMgsNewCallStack(profile, locationKey, timestamp, originType, callType, identifier, location, isEmergency, tsi);

			// Broadcast State Update to Peer RadioTetraAgent
			RadioStateUpdateBroadcaster::getInstance()->sendRadioAddCallStackEntry(message);
			LOG_GENERIC(SourceInfo, TA_Base_Core::DebugUtil::DebugInfo,
				"sendRadioAddCallStackEntry");
		}
		FUNCTION_EXIT;
	}

	void Radio::removeCallStackEntry(ta_uint32 timestamp, const char* tsi)
	{
		FUNCTION_ENTRY("removeCallStackEntry");
		TA_Base_Core::RACallStackHistoryAccessFactory::getInstance().deleteCallStackEntry(timestamp, tsi);

		if (m_active)
		{
			// Send comms message
			m_callback.sendCommsMgsDeleteCallStack(timestamp, tsi);

			// Broadcast State Update to Peer RadioTetraAgent
			RadioDeleteCallStackEntry message;
			message.timestamp = timestamp;
			message.tsi = tsi;

			RadioStateUpdateBroadcaster::getInstance()->sendRadioDeleteCallStackEntry(message);
			LOG_GENERIC(SourceInfo, TA_Base_Core::DebugUtil::DebugInfo,
				"sendRadioDeleteCallStackEntry");
		}

		FUNCTION_EXIT;
	}

