TA_Base_Bus::IRadioCorbaDef::PredefinedSDSMessage* Radio::getByShortName(const char* shortName)
{
	FUNCTION_ENTRY("getByShortName");
	// Get the SDS based on shortName from the database
	TA_Base_Core::IRAPredefinedSDSMessage* sdsMessage =
		TA_Base_Core::RAPredefinedSDSMessageAccessFactory::getInstance().getByShortName(shortName);

	// Create the selected call list for returning.
	TA_Base_Bus::IRadioCorbaDef::PredefinedSDSMessage* corbaSDSmessage =
		new TA_Base_Bus::IRadioCorbaDef::PredefinedSDSMessage();

	LOG_GENERIC(SourceInfo, TA_Base_Core::DebugUtil::DebugInfo,
		"getByShortName - short name : %s + message : %s", sdsMessage->getShortName(), sdsMessage->getMessage());
	if (sdsMessage->getShortName().size() == 1)
	{
		corbaSDSmessage->shortName = CORBA::string_dup(sdsMessage->getShortName().c_str());
		corbaSDSmessage->message = CORBA::string_dup(sdsMessage->getMessage().c_str());
	}
	else
	{
		LOG_GENERIC(SourceInfo, TA_Base_Core::DebugUtil::DebugInfo,
			"getByShortName - no message found with the short name : %s", shortName);

	}

	delete sdsMessage;
	sdsMessage = NULL;

	FUNCTION_EXIT;
	return corbaSDSmessage;
}

TA_Base_Bus::IRadioCorbaDef::PredefinedSDSMessageList* Radio::getSDSList(bool readWrite)
{
	FUNCTION_ENTRY("getSDSList");
	// Get the full SDS message list from the database
	std::vector<TA_Base_Core::IRAPredefinedSDSMessage*> sdsList = TA_Base_Core::RAPredefinedSDSMessageAccessFactory::getInstance().getList(false);

	// Create the selected call list for returning.
	TA_Base_Bus::IRadioCorbaDef::PredefinedSDSMessageList* corbaSDSlist =
		new TA_Base_Bus::IRadioCorbaDef::PredefinedSDSMessageList();

	// Set it's length (it's a CORBA sequence, and as such needs its length specifed, because
	// sequences don't automatically increase in size)
	corbaSDSlist->length(sdsList.size());

	// Now put the data from the IRAPredefinedSDSMessage into the PredefinedSDSMessage struct in the CORBA sequence
	for (unsigned int i = 0; i < sdsList.size(); i++)
	{
		(*corbaSDSlist)[i].shortName = sdsList[i]->getShortName().c_str();
		(*corbaSDSlist)[i].message = sdsList[i]->getMessage().c_str();

		

		// And delete the database member while we're here
		delete sdsList[i];
		sdsList[i] = NULL;
	}
	FUNCTION_EXIT;
	return corbaSDSlist;
}

