void Radio::insertDBPatchGroup(const char* patchName, const char* ownerTSI, const  std::vector<std::string>& patchMemberTSIs)
{
	FUNCTION_ENTRY("insertDBPatchGroup");
	// This group hasn't been deleted, so either create it or load it
	std::string firstTSI = patchMemberTSIs[0];
	std::string patchTsi = firstTSI;

	if (firstTSI.find('-') != std::string::npos)
		patchTsi = firstTSI.substr(0, firstTSI.find_first_of('-'));


	IRASubscribers* group = NULL;
	bool created = false;

	try
	{
		group = TA_Base_Core::RASubscribersAccessFactory::getInstance().getSubscriberDetails(patchTsi);
	}
	catch (TA_Base_Core::DataException & de)
	{
		LOG_GENERIC(SourceInfo, DebugUtil::DebugError,
			"Caught DataException, msg:\"%s\", data:\"%s\"",
			de.what(), de.getWhichData().c_str());
		LOG_EXCEPTION_CATCH(SourceInfo, "DataException", "Caught exception while attempting to load subscriber. This could simply be because the subscriber does not exist yet, or it could be another error");
		// If there was an error loading the item from the database, then try to create one instead
		try
		{
			// Need to work out the location key for the group
			ta_uint32 locationKey = 1; // Todo: Need to get the actual location key
			std::string locationName = "OCC"; // Todo: Need to get the actual location name
			group = new TA_Base_Core::RASubscribers(patchTsi,
				patchName,
				TA_Base_Core::IRASubscribers::PATCH_GROUP,
				locationName,
				locationKey,
				true,
				ownerTSI);

			// And save the group to the database
			group->applyChanges();

			created = true;
		}
		catch (...)
		{
			// If this fails - well, that's bad. Give up on this group and continue to the next one
			LOG_GENERIC(SourceInfo, DebugUtil::DebugError,
				"Non-recoverable error while attempting to create group with TSI: %s",
				patchTsi);
		}
	}
	catch (...)
	{
		// Otherwise this group is a lost cause
		LOG_GENERIC(SourceInfo, DebugUtil::DebugError,
			"Miscellaneous exception while attempting to load group with TSI: %s",
			patchTsi.c_str());
	}


	insertDBPatchGroupMembers(group, patchMemberTSIs);

	// update the GUI
	if (m_active && NULL != group)
	{
		if (created)
		{
			RadioDirectoryServant::notifySubscriberChange(group, IRadioDirectoryCallback::NEW_SUBSCRIBER);
		}
		else
		{
			RadioDirectoryServant::notifySubscriberChange(group, IRadioDirectoryCallback::UPDATE_SUBSCRIBER);
		}

		// Broadcast State Update to Peer RadioTetraAgent
		SubscriberStateUpdate message;
		message.notifyType = NEW_SUBSCRIBER;
		message.details.TSI = group->getTSI();
		message.details.subscriberName = group->getSubscriberName();
		message.details.locationName = group->getLocation();
		message.details.locationKey = group->getLocationKey();
		message.details.ownerTSI = group->getOwner();
		message.details.type = TA_IRS_App::PATCH_SUBSCRIBER;

		for (int idx = 0; idx < patchMemberTSIs.size(); idx++)
		{
			GroupDetails newGrp;
			newGrp.groupTSI = group->getTSI();
			newGrp.memberTSI = patchMemberTSIs[idx];
			message.groupList.push_back(newGrp);
		}

		RadioStateUpdateBroadcaster::getInstance()->sendRadioSubscriberUpdate(message);
		LOG_GENERIC(SourceInfo, TA_Base_Core::DebugUtil::DebugInfo,
			"sendRadioDeleteCallStackEntry");

		delete group;
		group = NULL;
	}

	FUNCTION_EXIT;
}

